mapper.select:
        select 

        FROM REP_DURATION
        LEFT JOIN 
        	FIN_PRODUCT F
        ON REP_DURATION.REP_FINPROD_ID = F.FINPROD_ID


        		AND F.FINPROD_MARKET_ID IN 

        			#{item}



        		AND REP_FINPROD_REG_ID = #{repFinprodRegId}


        		AND F.OPERATION_TYPE = #{issueType}


        		AND F.PROFIT_TYPE = #{profitType}


        		AND REP_STATUS_DATE BETWEEN STR_TO_DATE(#{dateSDate},'%Y-%m-%d') AND STR_TO_DATE(#{dateEDate},'%Y-%m-%d')


	        	AND CONCAT_WS('',REP_FINPROD_ID,',',DATE_FORMAT(REP_DURATION_REG_DATE,'%Y-%m-%d')) IN

        			#{item}
